    "itemId": "tcjS7ZEu6Fppiy3z",
    "itemType": "action",
    "itemName": "擒获 Grab",
    "itemFolderId": null,
    "itemSourceUuid": "Compendium.pf2e.bestiary-ability-glossary-srd.Item.Tkd8sH4pwFIPzqTr",
    "itemSlug": "grab",
    "itemRulesJSON": "[]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>@Localize[PF2E.NPC.Abilities.Glossary.Grab]</p>",
        "display": "<p><strong>需求</strong> 怪物的上一个动作是一次命中的打击，且其伤害条目中列有“擒获”；或者怪物正使一个生物处于@UUID[Compendium.pf2e.conditionitems.Item.kWc1fhmv9LBiTuei]{受擒}或@UUID[Compendium.pf2e.conditionitems.Item.VcDeM8A5oI6VqhbM]{束缚}状态。</p><hr /><p><strong>效果</strong> 如果在打击后使用，怪物尝试用发动该次攻击的身体部位[[/act grapple]]该生物。此次尝试不适用、也不计入多重攻击减值。</p><p>怪物也可以使用擒获，选择一个正被其具有擒获能力的肢体擒获或束缚的生物，自动将该状态延长至怪物的下个回合结束。</p>"
      }
    ],
    "normalizedBody": "@Localize[PF2E.NPC.Abilities.Glossary.Grab]",
