    "approved": true,
    "actorId": "Gva6GAH3WjjRi8Wd",
    "actorType": "npc",
    "actorName": "伦布尔斯·沃西 Rembles Worthy",
    "actorFolderId": "cGe8iQTsYWPjF3s7",
