    "itemName": "变形 Change Shape",
    "itemFolderId": null,
    "itemSourceUuid": "Compendium.pf2e.bestiary-ability-glossary-srd.Item.eQM5hQ1W3d1uen97",
    "itemSlug": "change-shape",
    "itemRulesJSON": "[{\"alwaysActive\":true,\"key\":\"RollOption\",\"label\":\"PF2E.NPCAbility.ChangeShape.Label\",\"option\":\"change-shape\",\"selection\":\"barghest\",\"suboptions\":[{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Barghest\",\"value\":\"barghest\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Animal.Specific.Dog\",\"value\":\"dog\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Humanoid.Humanoid\",\"value\":\"humanoid\"}],\"toggleable\":true,\"value\":true},{\"attackModifier\":13,\"damage\":{\"base\":{\"damageType\":\"piercing\",\"dice\":2,\"die\":\"d8\",\"modifier\":5}},\"key\":\"Strike\",\"label\":\"PF2E.BattleForm.Attack.Jaws\",\"predicate\":[{\"not\":\"change-shape:humanoid\"}],\"traits\":\"unholy\"},{\"key\":\"Note\",\"selector\":\"jaws-damage\",\"text\":\"@Localize[PF2E.NPC.Abilities.Glossary.Knockdown]\",\"title\":\"Knockdown\",\"visibility\":\"owner\"},{\"key\":\"BaseSpeed\",\"predicate\":[\"change-shape:dog\"],\"selector\":\"land\",\"value\":35},{\"key\":\"DamageDice\",\"override\":{\"damageType\":\"bludgeoning\"},\"predicate\":[\"change-shape:humanoid\"],\"selector\":\"claw-damage\"}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>The barghest takes on the shape of a humanoid, a dog, or its true form. Their size changes to match the new form. When the barghest is a humanoid, their claw Strike deals bludgeoning damage and they lose their jaws Strike. When the barghest is a dog, their Speed changes to 35 feet. Each individual barghest has only one humanoid form and one dog form.</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>The barghest takes on the shape of a humanoid, a dog, or its true form. Their size changes to match the new form. When the barghest is a humanoid, their claw Strike deals bludgeoning damage and they lose their jaws Strike. When the barghest is a dog, their Speed changes to 35 feet. Each individual barghest has only one humanoid form and one dog form.</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>犬魔可以变成类人生物、犬或自身的真实形态。其体型变为与新形态相符。处于类人生物形态时，其爪击打击造成钝击伤害，且失去颚咬打击。处于犬形态时，其速度变为35尺。每只犬魔都只有一种类人生物形态与一种犬形态。</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>犬魔可以变成类人生物、犬或自身的真实形态。其体型变为与新形态相符。处于类人生物形态时，其爪击打击造成钝击伤害，且失去颚咬打击。处于犬形态时，其速度变为35尺。每只犬魔都只有一种类人生物形态与一种犬形态。</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>",
