    "itemId": "RHsGeVOoFFoGYyZ1",
    "itemType": "action",
    "itemName": "变身 Change Shape",
    "itemFolderId": null,
    "itemSourceUuid": "Compendium.pf2e.bestiary-ability-glossary-srd.Item.eQM5hQ1W3d1uen97",
    "itemSlug": "change-shape",
    "itemRulesJSON": "[{\"alwaysActive\":true,\"key\":\"RollOption\",\"label\":\"PF2E.NPCAbility.ChangeShape.Label\",\"option\":\"change-shape\",\"selection\":\"humanoid\",\"suboptions\":[{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.LamiaMatriarch\",\"value\":\"lamia\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Humanoid.Humanoid\",\"value\":\"humanoid\"}],\"toggleable\":true,\"value\":true},{\"key\":\"CreatureSize\",\"value\":\"medium\",\"predicate\":[\"change-shape:humanoid\"]},{\"key\":\"TokenImage\",\"ring\":{\"subject\":{\"texture\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/Dini.webp\"},\"colors\":{}},\"predicate\":[\"change-shape:humanoid\"],\"scale\":1,\"value\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/Dini.webp\"}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>The lamia matriarch can take on the appearance of a Medium humanoid. This doesn't change their Speed or their attack and damage modifiers with their Strikes, but it does prevent them from using their cursed touch. Each lamia matriarch has a fixed humanoid form that resembles their upper torso when in their true form. This is the only humanoid form they can adopt using this ability.</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>The lamia matriarch can take on the appearance of a Medium humanoid. This doesn't change their Speed or their attack and damage modifiers with their Strikes, but it does prevent them from using their cursed touch. Each lamia matriarch has a fixed humanoid form that resembles their upper torso when in their true form. This is the only humanoid form they can adopt using this ability.</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>拉米亚女族长可以呈现出中型类人生物的外貌。这不会改变其速度，或打击的攻击与伤害调整值，但会使其无法使用带有诅咒的接触能力。每个拉米亚女族长都有一种固定的类人生物形态，与其真身的上半身相似。这是它使用此能力唯一能变成的类人生物形态。</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>拉米亚女族长可以呈现出中型类人生物的外貌。这不会改变其速度，或打击的攻击与伤害调整值，但会使其无法使用带有诅咒的接触能力。每个拉米亚女族长都有一种固定的类人生物形态，与其真身的上半身相似。这是它使用此能力唯一能变成的类人生物形态。</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>",
