    "itemRulesJSON": "[{\"alwaysActive\":true,\"key\":\"RollOption\",\"label\":\"PF2E.NPCAbility.ChangeShape.Label\",\"option\":\"change-shape\",\"suboptions\":[{\"label\":\"Tikbalang\",\"value\":\"tikbalang\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Humanoid.Medium\",\"value\":\"humanoid-medium\"}],\"toggleable\":true,\"value\":true,\"selection\":\"tikbalang\"},{\"key\":\"TokenImage\",\"ring\":{\"subject\":{\"texture\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/Utgar.webp\"},\"colors\":{}},\"predicate\":[\"change-shape:humanoid-medium\"],\"value\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/Utgar.webp\",\"scale\":1,\"animation\":{\"transition\":\"morph\"}},{\"key\":\"CreatureSize\",\"predicate\":[\"change-shape:humanoid-medium\"],\"value\":\"medium\"}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>The tikbalang takes on the appearance of any Medium or Large humanoid. This doesn't change the tikbalang's Speed or their attack and damage modifiers with their Strikes.</p><hr><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>The tikbalang takes on the appearance of any Medium or Large humanoid. This doesn't change the tikbalang's Speed or their attack and damage modifiers with their Strikes.</p><hr><p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>提克巴兰呈现出任意中型或大型类人生物的外貌。这不会改变提克巴兰的速度，也不会改变其打击的攻击和伤害调整值。</p><hr><p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>提克巴兰呈现出任意中型或大型类人生物的外貌。这不会改变提克巴兰的速度，也不会改变其打击的攻击和伤害调整值。</p><hr><p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>",
