    "itemRulesJSON": "[{\"alwaysActive\":true,\"key\":\"RollOption\",\"label\":\"PF2E.NPCAbility.ChangeShape.Label\",\"option\":\"change-shape\",\"selection\":\"humanoid-medium\",\"suboptions\":[{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Rakshasa.RajaKrodha\",\"value\":\"raja-krodha\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Humanoid.Medium\",\"value\":\"humanoid-medium\"}],\"toggleable\":true,\"value\":true},{\"key\":\"TokenImage\",\"value\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/ElfLinisriel.webp\",\"ring\":{\"subject\":{\"texture\":\"modules/pf2e-bastion-of-blasphemies/assets/actors/subjects/ElfLinisriel.webp\"},\"colors\":{}},\"predicate\":[\"change-shape:humanoid-medium\"]}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>The raja-krodha takes on the appearance of any Medium humanoid. This doesn't change the raja-krodha's Speed or their attack and damage modifiers with their Strikes but might change the damage type their Strikes deal (typically to bludgeoning). They lose their fangs Strike unless the humanoid form has fangs or a similar unarmed attack.</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>The raja-krodha takes on the appearance of any Medium humanoid. This doesn't change the raja-krodha's Speed or their attack and damage modifiers with their Strikes but might change the damage type their Strikes deal (typically to bludgeoning). They lose their fangs Strike unless the humanoid form has fangs or a similar unarmed attack.</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>忿怒罗刹呈现出任意中型类人生物的外貌。这不会改变忿怒罗刹的速度，或其打击的攻击与伤害调整值，但可能改变打击造成的伤害类型（通常变为钝击）。它会失去獠牙打击，除非该类人生物形态具有獠牙或类似的徒手攻击。</p>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>忿怒罗刹呈现出任意中型类人生物的外貌。这不会改变忿怒罗刹的速度，或其打击的攻击与伤害调整值，但可能改变打击造成的伤害类型（通常变为钝击）。它会失去獠牙打击，除非该类人生物形态具有獠牙或类似的徒手攻击。</p>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变形变成某个特定个体的样貌。使用变形视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变形能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>",
    "sourceSha256": "e3796a929ae28b520604051a771215ebe960be0f0a224e741cb7a042f626e3ef",
