    "actorType": "npc",
    "actorName": "普罗勒斯·阿鲁多拉 Prollus Arudora",
    "actorFolderId": "IDeegHUXlrynZ2Jw",
    "actorSourceUuid": "Compendium.pf2e.pathfinder-monster-core.Actor.pPQyoQHTxrE2U7px",
    "itemId": "QpzMidSalFaHGivw",
    "itemType": "action",
    "itemName": "变身 Change Shape",
    "itemFolderId": null,
    "itemSourceUuid": "Compendium.pf2e.bestiary-family-ability-glossary.Item.ZMTnwyXjyfy7Ryi6",
    "itemSlug": "vampire-true-change-shape",
    "itemRulesJSON": "[{\"alwaysActive\":true,\"key\":\"RollOption\",\"label\":\"PF2E.NPCAbility.ChangeShape.Label\",\"option\":\"change-shape\",\"selection\":\"vampire\",\"suboptions\":[{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Vampire\",\"value\":\"vampire\"},{\"label\":\"PF2E.NPCAbility.ChangeShape.Form.Animal.Specific.BatGiant\",\"value\":\"bat-giant\"}],\"toggleable\":true,\"value\":true},{\"attackModifier\":15,\"damage\":{\"base\":{\"damageType\":\"piercing\",\"dice\":1,\"die\":\"d8\",\"modifier\":9}},\"key\":\"Strike\",\"label\":\"PF2E.BattleForm.Attack.Fangs\",\"predicate\":[\"change-shape:bat-giant\"],\"replaceAll\":true}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>The vampire transforms into one of its animal forms or back into its normal form. Most vampires can turn into a bat, but some can turn into a different creature, such as a rat or a wolf.</p>\n<ul>\n<li><strong>Giant Bat</strong>\n<ul>\n<li><strong>Senses</strong> echolocation 40 feet,</li>\n<li><strong>Speed</strong> 20 feet, fly 30 feet,</li>\n<li><strong>Melee</strong> fangs +15 <strong>Damage</strong> 1d8+9 piercing</li>\n</ul>\n</li>\n</ul>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>The vampire transforms into one of its animal forms or back into its normal form. Most vampires can turn into a bat, but some can turn into a different creature, such as a rat or a wolf.</p>\n<ul>\n<li><strong>Giant Bat</strong>\n<ul>\n<li><strong>Senses</strong> echolocation 40 feet,</li>\n<li><strong>Speed</strong> 20 feet, fly 30 feet,</li>\n<li><strong>Melee</strong> fangs +15 <strong>Damage</strong> 1d8+9 piercing</li>\n</ul>\n</li>\n</ul>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>吸血鬼变为其动物形态之一，或变回通常形态。大多数吸血鬼能变成蝙蝠，但一些吸血鬼会变成不同的生物，例如老鼠或狼。</p>\n<ul>\n<li><strong>巨型蝙蝠</strong>\n<ul>\n<li><strong>感官</strong> 回声定位40尺，</li>\n<li><strong>速度</strong> 20尺，飞行30尺，</li>\n<li><strong>近战</strong> 尖牙 +15 <strong>伤害</strong> 1d8+9穿刺</li>\n</ul>\n</li>\n</ul>\n<hr>\n<p>@Localize[PF2E.NPC.Abilities.Glossary.ChangeShape]</p>",
        "display": "<p>吸血鬼变为其动物形态之一，或变回通常形态。大多数吸血鬼能变成蝙蝠，但一些吸血鬼会变成不同的生物，例如老鼠或狼。</p>\n<ul>\n<li><strong>巨型蝙蝠</strong>\n<ul>\n<li><strong>感官</strong> 回声定位40尺，</li>\n<li><strong>速度</strong> 20尺，飞行30尺，</li>\n<li><strong>近战</strong> 尖牙 +15 <strong>伤害</strong> 1d8+9穿刺</li>\n</ul>\n</li>\n</ul>\n<hr>\n<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>怪物改变自身形态，持续时间不限。它可以再次使用此动作恢复自然形态或采取新形态。除非另有说明，否则怪物无法使用变身变成某个特定个体的样貌。使用变身视为制作了用于欺骗技能@UUID[Compendium.pf2e.actionspf2e.Item.AJstokjdG6iDjVjE]{乔装}用途的伪装。若只是判断怪物是否属于它变成的族裔或生物类型，这种变化会自动战胜察觉DC；此外，怪物的欺骗DC获得+4状态加值，以防他人识破其伪装。变身能力会说明怪物可以采取哪些形态。怪物只获得新形态的身体形态，不会获得其特殊能力。例如，在每种形态下，它的正常速度与打击会被替换，感官或体型也可能改变。所有变化都会列在属性栏中。</p>",
