    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>@Localize[PF2E.NPC.Abilities.Glossary.Telepathy]</p>",
        "display": "<p>具有心灵感应能力的怪物可以与所列范围内的任何生物进行心灵交流，只要双方有共同语言。这并不赋予它窥探对方思想的特殊能力，所交流的信息也不会超过正常言语。</p>"
      }
    ],
