        "display": "<p><strong>需求</strong>怪物的最后的动作是一次命中的打击，在其伤害条目中列有“击倒”。</p><hr /><p><strong>效果</strong> 怪物尝试[[/act trip]]生物。该尝试不适用也不累计怪物的多重攻击减值。</p>"
