    "normalizedBody": "@Localize[PF2E.NPC.Abilities.Glossary.Regeneration]",
    "displayFragment": "<p>怪物在每个自己的回合开始时恢复所列数量的生命值。只要再生仍在生效，它的@UUID[Compendium.pf2e.conditionitems.Item.yZRUzMqrMmfLu0V1]{濒死}状态就不会超过濒死3。但如果它受到再生条目所列类型的伤害，再生会失效，直到它的下个回合结束。应在施加该类型伤害之前使再生失效，因为这次伤害可能让怪物达到濒死4而死亡。</p>",
