    "forms": [
      {
        "kind": "source",
        "source": "<p>@Localize[PF2E.NPC.Abilities.Glossary.Tremorsense]</p>",
        "display": "<p>震颤感知使怪物能够感受到由移动引起、经固体表面传递的振动。这是一种范围有限的模糊感官，具体范围列于该能力中。只有怪物与目标处于同一表面，并且目标正沿该表面移动或在其中掘穴穿行时，震颤感知才会生效。</p>"
      }
    ],
