    "actorSourceUuid": "Compendium.pf2e.bastion-of-blasphemies-bestiary.Actor.xDNjxFXDFtl9thUa",
    "itemId": "5nDsM5uh1o3R9QeR",
    "itemType": "action",
    "itemName": "恐怖威压 Frightful Presence",
    "itemFolderId": null,
    "itemSourceUuid": "Compendium.pf2e.bestiary-ability-glossary-srd.Item.etMnv73EIdEZrYYu",
    "itemSlug": "frightful-presence",
    "itemRulesJSON": "[{\"key\":\"Aura\",\"radius\":30,\"slug\":\"frightful-presence\",\"traits\":[\"emotion\",\"fear\",\"mental\"]}]",
    "itemGM": "",
    "forms": [
      {
        "kind": "source",
        "source": "<p>30 feet. @Check[will|dc:23|options:area-effect,inflicts:frightened]</p><hr><p>@Localize[PF2E.NPC.Abilities.Glossary.FrightfulPresence]</p>",
        "display": "<p>30 feet. @Check[will|dc:23|options:area-effect,inflicts:frightened]</p><hr><p>首次进入该区域的生物必须尝试一次意志豁免。</p>\n<p>无论豁免结果如何，该生物都会临时免疫这只怪物的恐怖威压，持续1分钟。</p>\n<hr />\n<p><strong>大成功</strong> 该生物不受此威压影响。</p>\n<p><strong>成功</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧1}。</p>\n<p><strong>失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧2}。</p>\n<p><strong>大失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧4}。</p>"
      },
      {
        "kind": "approved-canonical",
        "source": "<p>30尺。@Check[will|dc:23|options:area-effect,inflicts:frightened]</p><hr><p>@Localize[PF2E.NPC.Abilities.Glossary.FrightfulPresence]</p>",
        "display": "<p>30尺。@Check[will|dc:23|options:area-effect,inflicts:frightened]</p><hr><p>首次进入该区域的生物必须尝试一次意志豁免。</p>\n<p>无论豁免结果如何，该生物都会临时免疫这只怪物的恐怖威压，持续1分钟。</p>\n<hr />\n<p><strong>大成功</strong> 该生物不受此威压影响。</p>\n<p><strong>成功</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧1}。</p>\n<p><strong>失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧2}。</p>\n<p><strong>大失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧4}。</p>"
      }
    ],
    "normalizedBody": null,
    "displayFragment": "<p>首次进入该区域的生物必须尝试一次意志豁免。</p>\n<p>无论豁免结果如何，该生物都会临时免疫这只怪物的恐怖威压，持续1分钟。</p>\n<hr />\n<p><strong>大成功</strong> 该生物不受此威压影响。</p>\n<p><strong>成功</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧1}。</p>\n<p><strong>失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧2}。</p>\n<p><strong>大失败</strong> 该生物陷入@UUID[Compendium.pf2e.conditionitems.Item.TBSHQspnbcqxsmjL]{惊惧4}。</p>",
